fix.code:
// 1. Phía client: tolerant reader, giá trị lạ thành UNKNOWN thay vì làm hỏng cả trang
enum OrderStatus { PENDING, PAID, SHIPPED, @JsonEnumDefaultValue UNKNOWN }

record OrderSummary(
        long id,
        @JsonFormat(with = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_USING_DEFAULT_VALUE)
        OrderStatus status,
        long total) {}
// Màn hình hiện "Trạng thái khác" cho UNKNOWN; switch trên OrderStatus phải có nhánh default.

// 2. Phía server: tài liệu OpenAPI ghi rõ enum có thể có thêm giá trị
//    (x-extensible-enum), và thay đổi enum đi qua contract test của các consumer.
//    Hoặc giữ nguyên status cũ cho client v1 và thêm trường mới:
// {"id":2,"status":"PAID","refundStatus":"PARTIAL","refundedAmount":30000,"total":90000}
